const store = $getWorkflowStaticData("global");
const now = new Date();
const yesterday = new Date(now);
yesterday.setDate(yesterday.getDate() - 1);
const fmt = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
const startDate = "2026-01-01";
const endDate = fmt(yesterday);
store.startDate = startDate;
store.endDate = endDate;
store.hsCompanies = [];
store.hsCursor = null;
store.pendingInvoiceNotes = [];
store.pendingDroppedOrders = [];
store._orphanCheckedCompanies = {};
store.soReconciliation = {};
store.runSummary = { created: [], soInvoiced: [], soDeleted: [], soCreated: [], soUpdated: [] };
store.companyNames = store.companyNames || {};
store.excelRows = [];
return [{ json: { startDate, endDate } }];

const store = $getWorkflowStaticData('global');
store.hsCompanies = [];
store.hsCursor = null;
return [{ json: { initialized: true } }];

const store = $getWorkflowStaticData('global');
const payload = {
  filterGroups: [{
    filters: [
      { propertyName: 'relationship',        operator: 'EQ',         value: 'Distribution Center' },
      { propertyName: 'erp_account_number',  operator: 'HAS_PROPERTY' }
    ]
  }],
  properties: ['hs_object_id','erp_account_number','name'],
  limit: 200
};
if (store.hsCursor) payload.after = store.hsCursor;
return [{ json: payload }];

const response = $input.first().json;
const results = response.results || [];
const store = $getWorkflowStaticData('global');
if (!store.hsCompanies) store.hsCompanies = [];
store.hsCompanies.push(...results);
const nextCursor = response.paging?.next?.after;
store.hsCursor = (nextCursor && results.length > 0) ? nextCursor : null;
const hasMore = store.hsCursor !== null ? 1 : 0;
return [{ json: { fetched: store.hsCompanies.length, thisPage: results.length, hasMore } }];

const store = $getWorkflowStaticData('global');
const companies = store.hsCompanies || [];
const hsIdMap = {};
const output = [];
for (const c of companies) {
  const no = String(c.properties?.erp_account_number || '').trim();
  if (no) {
    hsIdMap[no] = c.id;
    output.push({ json: { customerNo: no, hsId: c.id } });
  }
}
store.hsIdMap = hsIdMap;
store.customerNos = output.map(o => o.json.customerNo);
if (output.length === 0) return [{ json: { customerNo: null, hsId: null } }];
return output;

const batchItems = $input.all();
const store = $getWorkflowStaticData('global');

const getYesterday = () => {
  const now = new Date();
  const yesterday = new Date(now);
  yesterday.setDate(yesterday.getDate() - 1);
  const fmt = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const startDate = fmt(yesterday);
  return { startDate, endDate: startDate };
};

const { startDate, endDate } = (store.startDate && store.endDate)
  ? { startDate: store.startDate, endDate: store.endDate }
  : getYesterday();

const customerNos = batchItems
  .map(i => String(i.json.customerNo || '').trim())
  .filter(no => no && no !== 'null');

const uniqueNos = [...new Set(customerNos)];
if (uniqueNos.length === 0) {
  return [{ json: { filter: null, customerNos: [], skip: true } }];
}
const customerFilter = uniqueNos.map(no => `Sell_to_Customer_No eq '${no.replace(/'/g,"''")}'`).join(' or ');
const filter = `Type eq 'Item' and ERC_Posting_Date ge ${startDate} and ERC_Posting_Date le ${endDate} and (${customerFilter})`;
return [{ json: { filter, startDate, endDate, customerNos: uniqueNos, skip: false } }];

const invoices = $input.all().map(i => i.json);
const store = $getWorkflowStaticData('global');
const hsIdMap = store.hsIdMap || {};

const fmt = v => `$${Number(v||0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

const DATA_BG    = '#ffffff';
const DATA_FG    = '#1a1a1a';
const HEADER_BG  = '#2d2d2d';
const HEADER_FG  = '#ffffff';
const BORDER     = '1px solid #888';

const notes = [];
for (const inv of invoices) {
  let lines = inv.salesInvoiceLines || [];
  if (lines.length === 0) continue;

  const hsId = hsIdMap[String(inv.customerNumber || '').trim()];
  if (!hsId) continue;

  lines = lines.filter(l => Number(l.quantity||0) !== 0);
  if (lines.length === 0) continue;
  lines = [...lines].sort((a,b) => String(a.lineObjectNumber||'').localeCompare(String(b.lineObjectNumber||'')));

  for (const l of lines) {
    store.excelRows.push({
      'Document No': inv.number || '',
      'Sell-to Customer No': inv.customerNumber || '',
      'Sell-to Customer Name': inv.customerName || '',
      'Item No': l.lineObjectNumber || '',
      'Description': l.description || '',
      'Posting Date': inv.postingDate || '',
      'Requested Delivery Date': inv.requestedDeliveryDate || '',
      'Order No': inv.orderNumber || '',
      'PO Number': inv.poNumber || '',
      'Quantity': Number(l.quantity || 0),
      'Unit Price': Number(l.unitPrice || 0),
      'Amount': Number(l.lineAmount || 0)
    });
  }

  const rowsHtml = lines.map(l => `
    <tr>
      <td style="padding:4px 8px;border:${BORDER};background:${DATA_BG};color:${DATA_FG};">${l.lineObjectNumber||''}</td>
      <td style="padding:4px 8px;border:${BORDER};background:${DATA_BG};color:${DATA_FG};">${l.description||''}</td>
      <td style="padding:4px 8px;border:${BORDER};background:${DATA_BG};color:${DATA_FG};text-align:right;">${fmt(l.unitPrice)}</td>
      <td style="padding:4px 8px;border:${BORDER};background:${DATA_BG};color:${DATA_FG};text-align:right;">${Number(l.quantity||0).toLocaleString('en-US')}</td>
      <td style="padding:4px 8px;border:${BORDER};background:${DATA_BG};color:${DATA_FG};text-align:right;">${fmt(l.lineAmount)}</td>
    </tr>`).join('');

  const totalQty    = lines.reduce((s,l) => s + Number(l.quantity||0), 0);
  const totalAmount = lines.reduce((s,l) => s + Number(l.lineAmount||0), 0);

  const body = `
<p style="margin:0 0 6px 0;">
  <span style="white-space:nowrap;"><strong>Sales Order:</strong> ${inv.orderNumber||'N/A'}</span> <span style="white-space:nowrap;"><strong>PO:</strong> ${inv.poNumber||'N/A'}</span> <span style="white-space:nowrap;"><strong>Status:</strong> Invoiced (${inv.number})</span> <span style="white-space:nowrap;"><strong>Requested Delivery:</strong> ${inv.requestedDeliveryDate||inv.postingDate||''}</span>${(inv.requestedDeliveryDate && inv.postingDate && inv.requestedDeliveryDate !== inv.postingDate) ? ` <span style="white-space:nowrap;"><strong>Posting Date:</strong> ${inv.postingDate}</span>` : ''}
</p>
<table style="border-collapse:collapse;width:100%;font-size:13px;">
  <thead>
    <tr>
      <th style="padding:4px 8px;border:${BORDER};background:${HEADER_BG};color:${HEADER_FG};text-align:left;">No.</th>
      <th style="padding:4px 8px;border:${BORDER};background:${HEADER_BG};color:${HEADER_FG};text-align:left;">Description</th>
      <th style="padding:4px 8px;border:${BORDER};background:${HEADER_BG};color:${HEADER_FG};text-align:right;">Unit Price</th>
      <th style="padding:4px 8px;border:${BORDER};background:${HEADER_BG};color:${HEADER_FG};text-align:right;">Qty</th>
      <th style="padding:4px 8px;border:${BORDER};background:${HEADER_BG};color:${HEADER_FG};text-align:right;">Amount</th>
    </tr>
  </thead>
  <tbody>
    ${rowsHtml}
    <tr>
      <td colspan="3" style="padding:4px 8px;border:${BORDER};background:${HEADER_BG};color:${HEADER_FG};text-align:right;font-weight:bold;">TOTAL</td>
      <td style="padding:4px 8px;border:${BORDER};background:${HEADER_BG};color:${HEADER_FG};text-align:right;font-weight:bold;">${totalQty.toLocaleString('en-US')}</td>
      <td style="padding:4px 8px;border:${BORDER};background:${HEADER_BG};color:${HEADER_FG};text-align:right;font-weight:bold;">${fmt(totalAmount)}</td>
    </tr>
  </tbody>
</table>`;

  store.companyNames[hsId] = inv.customerName || hsId;
  notes.push({ invoiceNo: inv.number, hsCompanyId: hsId, postingDate: inv.postingDate, body: body.trim(), soOrderNo: inv.orderNumber || '', soInvoiceNo: inv.number });
}

store.pendingInvoiceNotes = store.pendingInvoiceNotes || [];
store.pendingInvoiceNotes.push(...notes);

return [{ json: { done: true } }];

const lines = $input.first().json.value || [];
const byDoc = {};
for (const l of lines) {
  const doc = l.Document_No;
  if (!byDoc[doc]) byDoc[doc] = {
    number: doc,
    orderNumber: l.Order_No,
    customerNumber: l.Sell_to_Customer_No,
    customerName: l.Sell_to_Customer_Name,
    postingDate: l.ERC_Posting_Date,
    salesInvoiceLines: []
  };
  byDoc[doc].salesInvoiceLines.push({
    lineObjectNumber: l.No,
    description: l.Description,
    quantity: l.Quantity,
    unitPrice: l.Unit_Price,
    lineAmount: l.Amount
  });
}
return Object.values(byDoc).map(inv => ({ json: inv }));

const invoices = $input.all().map(i => i.json);
const store = $getWorkflowStaticData('global');
store.pendingInvoices = invoices;

const docNos = [...new Set(invoices.map(i => i.number))];
const filter = docNos.length
  ? docNos.map(no => `No eq '${no.replace(/'/g,"''")}'`).join(' or ')
  : "No eq 'SKIP'";

return [{ json: { filter } }];

const store = $getWorkflowStaticData('global');
const invoices = store.pendingInvoices || [];
const headers = $input.first().json.value || [];
const poMap = {}, deliveryMap = {}, postingMap = {}, orderNoMap = {};
for (const h of headers) {
  poMap[h.No] = h.External_Document_No;
  deliveryMap[h.No] = h.Requested_Delivery_Date_SOD || '';
  postingMap[h.No] = h.Posting_Date || '';
  orderNoMap[h.No] = h.Order_No || '';
}
return invoices.map(inv => {
  const requestedDelivery = deliveryMap[inv.number] || '';
  const postingDate = postingMap[inv.number] || inv.postingDate || '';
  return { json: { ...inv, poNumber: poMap[inv.number] || '', requestedDeliveryDate: requestedDelivery, postingDate, orderNumber: orderNoMap[inv.number] || inv.orderNumber || '' } };
});

const store = $getWorkflowStaticData('global');
const rows = store.excelRows || [];

if (rows.length === 0) {
  return [{ json: { message: 'No invoice data to export', rowCount: 0 } }];
}

return [{ json: { rows, rowCount: rows.length } }];

