const XLSX = require('xlsx');

const inputData = $input.first().json;
if (!inputData.rows || inputData.rows.length === 0) {
  return [{ json: { message: 'No data to generate Excel file' } }];
}

const rows = inputData.rows;
const workbook = XLSX.utils.book_new();
const worksheet = XLSX.utils.json_to_sheet(rows);

const colWidths = [
  { wch: 14 },
  { wch: 20 },
  { wch: 30 },
  { wch: 12 },
  { wch: 35 },
  { wch: 14 },
  { wch: 22 },
  { wch: 12 },
  { wch: 14 },
  { wch: 10 },
  { wch: 12 },
  { wch: 12 }
];
worksheet['!cols'] = colWidths;

XLSX.utils.book_append_sheet(workbook, worksheet, 'Invoices');

const now = new Date();
const dateStr = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
const fileName = `Route21_Invoice_Export_${dateStr}.xlsx`;

const buffer = XLSX.write(workbook, { bookType: 'xlsx', type: 'buffer' });

return [{
  json: { fileName, rowCount: rows.length },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      fileName: fileName
    }
  }
}];
